import React from 'react';
import { FaMapMarkerAlt, FaCalendar, FaClock, FaUsers, FaVolleyballBall, FaEdit, FaTrash, FaRubleSign } from 'react-icons/fa';
import Button from '../common/Button/Button';
import styles from './AdvertCard.module.css';

const AdvertCard = ({ advert, isCreator, isParticipating, onSubscribe, onEdit, onDelete, onClick }) => {
    const levelColors = {
        'D1': '#10B981',
        'D2': '#3B82F6',
        'D3': '#F59E0B',
        'D4': '#EF4444',
        'D4Plus': '#8B5CF6'
    };

    const formatDate = (dateStr) => {
        if (!dateStr) return '';
        const date = new Date(dateStr);
        const day = date.getDate();
        const month = date.toLocaleString('ru-RU', { month: 'long' });
        const year = date.getFullYear();
        return `${day} ${month} ${year} г.`;
    };

    const formatTime = (timeStr) => {
        if (!timeStr) return '';

        // Если timeStr уже строка вида "HH:MM:SS"
        if (typeof timeStr === 'string') {
            const parts = timeStr.split(':');
            if (parts.length >= 2) {
                return `${parts[0]}:${parts[1]}`;
            }
            return timeStr;
        }

        // Если timeStr это Date объект или строка с датой
        try {
            const date = new Date(timeStr);
            if (!isNaN(date.getTime())) {
                const hours = date.getHours().toString().padStart(2, '0');
                const minutes = date.getMinutes().toString().padStart(2, '0');
                return `${hours}:${minutes}`;
            }
        } catch (e) {
            console.error('Error formatting time:', e);
        }

        return '';
    };

    const getGameLevelName = (level) => {
        const levelMap = {
            1: 'D1',
            2: 'D2',
            3: 'D3',
            4: 'D4',
            5: 'D4Plus',
            'D1': 'D1',
            'D2': 'D2',
            'D3': 'D3',
            'D4': 'D4',
            'D4Plus': 'D4Plus'
        };
        const levelName = levelMap[level] || 'D2';
        return levelName === 'D4Plus' ? 'D4+' : levelName;
    };

    const participantsCount = advert.participantsCount || 0;
    const progressPercent = (participantsCount / advert.peopleCount) * 100;

    return (
        <div className={styles.card} onClick={onClick}>
            <div className={styles.cardHeader}>
                <div className={styles.levelBadge} style={{ background: levelColors[getGameLevelName(advert.gameLevel)] || '#667eea' }}>
                    <FaVolleyballBall className={styles.levelIcon} />
                    <span>Уровень {getGameLevelName(advert.gameLevel)}</span>
                </div>
                {isCreator && <div className={styles.creatorBadge}>Ваше объявление</div>}
                {isParticipating && !isCreator && <div className={styles.participatingBadge}>Вы участвуете</div>}
            </div>

            <div className={styles.cardContent}>
                <div className={styles.row}>
                    <FaMapMarkerAlt className={styles.icon} />
                    <span className={styles.text}>{advert.address}</span>
                </div>

                <div className={styles.row}>
                    <FaCalendar className={styles.icon} />
                    <span className={styles.text}>{formatDate(advert.date)}</span>
                </div>

                <div className={styles.row}>
                    <FaClock className={styles.icon} />
                    <span className={styles.text}>{formatTime(advert.startTime)} - {formatTime(advert.endTime)}</span>
                </div>

                <div className={styles.participantsSection}>
                    <div className={styles.participantsHeader}>
                        <FaUsers className={styles.icon} />
                        <span className={styles.label}>Участники</span>
                    </div>
                    <div className={styles.participantsCount}>
                        <span className={styles.currentCount}>{participantsCount}</span>
                        <span className={styles.separator}>/</span>
                        <span className={styles.totalCount}>{advert.peopleCount}</span>
                    </div>
                    <div className={styles.progressBar}>
                        <div className={styles.progressFill} style={{ width: `${progressPercent}%` }}></div>
                    </div>
                </div>

                <div className={styles.row}>
                    <FaRubleSign className={styles.icon} />
                    <span className={styles.label}>Стоимость</span>
                    <span className={styles.priceValue}>{advert.cost} BYN</span>
                </div>
            </div>

            <div className={styles.cardFooter} onClick={(e) => e.stopPropagation()}>
                {isCreator ? (
                    <div className={styles.creatorActions}>
                        <Button size="small" variant="outline" onClick={onEdit}>
                            <FaEdit /> Редактировать
                        </Button>
                        <Button size="small" variant="danger" onClick={onDelete}>
                            <FaTrash /> Удалить
                        </Button>
                    </div>
                ) : (
                    <Button size="medium" fullWidth variant={isParticipating ? 'secondary' : 'primary'} onClick={onSubscribe}>
                        {isParticipating ? 'Отменить запись' : 'Записаться'}
                    </Button>
                )}
            </div>
        </div>
    );
};

export default AdvertCard;
